function n(v){
  if(v===null||v===undefined||v==='') return null;
  if(typeof v==='number') return Number.isFinite(v)?v:null;
  let s=String(v).replace(/\$/g,'').replace(/\s/g,'').trim();
  if(!s) return null;
  if(s.includes(',')&&s.includes('.')) s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'');
  else if(s.includes(',')) s=s.replace(/\./g,'').replace(',','.');
  const x=Number(s.replace(/[^\d.-]/g,'')); return Number.isFinite(x)?x:null;
}
const rows=$('M4 - Leer Movimientos FX').all().map(i=>i.json).filter(r=>r.ID);
const needsBlue=rows.some(r=>String(r.Clase||'')==='Egreso' && String(r['Moneda original']||'').toUpperCase()==='USD' && String(r['Estado revisión']||'').toUpperCase()!=='ANULADO' && (n(r['Monto ARS'])===null || Math.abs(n(r['Monto ARS'])||0)<1e-12) && !(n(r['Cotización ARS'])>0));
return [{json:{needs_blue:needsBlue,rows_count:rows.length}}];

function numOrNull(v){
  if(v===null||v===undefined||v==='') return null;
  if(typeof v==='number') return Number.isFinite(v)?v:null;
  let s=String(v).replace(/\$/g,'').replace(/\s/g,'').trim();
  if(!s) return null;
  if(s.includes(',')&&s.includes('.')) s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'');
  else if(s.includes(',')) s=s.replace(/\./g,'').replace(',','.');
  const n=Number(s.replace(/[^\d.-]/g,'')); return Number.isFinite(n)?n:null;
}
function dateKey(v){
  if(v===null||v===undefined||v==='')return null;
  if(typeof v==='number'){const d=new Date(Date.UTC(1899,11,30)+Number(v)*86400000);return d.toISOString().slice(0,10);}
  const s=String(v); let m=s.match(/^(\d{4})-(\d{2})-(\d{2})/); if(m)return `${m[1]}-${m[2]}-${m[3]}`;
  m=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/); if(m){let y=Number(m[3]);if(y<100)y+=2000;return `${y}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`;}
  const d=new Date(s); return isNaN(d)?null:d.toISOString().slice(0,10);
}
function diffDays(a,b){return Math.round((new Date(a+'T00:00:00Z')-new Date(b+'T00:00:00Z'))/86400000);}
const rows=$('M4 - Leer Movimientos FX').all().map(i=>i.json).filter(r=>r.ID);
let blueHist=[];
try{
  const rr=$('M4 - Obtener histórico blue ArgentinaDatos').all().map(i=>i.json),flat=[];
  for(const j of rr){if(Array.isArray(j))flat.push(...j);else if(Array.isArray(j?.data))flat.push(...j.data);else if(Array.isArray(j?.body))flat.push(...j.body);else if(j&&j.fecha)flat.push(j);}
  blueHist=flat.map(r=>({fecha:dateKey(r.fecha),venta:numOrNull(r.venta)})).filter(r=>r.fecha&&r.venta>0).sort((a,b)=>a.fecha.localeCompare(b.fecha));
}catch(e){blueHist=[];}
function blueForDate(d){
  if(!d||!blueHist.length)return null; let best=null;
  for(const q of blueHist){if(q.fecha>d)break;best=q;}
  if(!best)return null; const lag=diffDays(d,best.fecha); if(lag<0||lag>7)return null;
  return {rate:best.venta,source:best.fecha===d?'BLUE API':'BLUE API ÚLTIMO HÁBIL'};
}
const purchases=rows.filter(r=>{
  const cur=String(r['Moneda original']||'').toUpperCase(),sub=String(r.Subtipo||'').toLowerCase(),det=String(r.Detalle||'').toLowerCase();
  const a=numOrNull(r['Monto ARS']),u=numOrNull(r['Monto original']);
  return r.Clase==='Transferencia'&&cur==='USD'&&a!==null&&Math.abs(a)>0&&u!==null&&Math.abs(u)>0&&(sub.includes('compra de moneda extranjera')||det.includes('compra moneda extran')||det.includes('compra venta de dolares'));
});
function realRate(r){
  const d=dateKey(r.Fecha),u=numOrNull(r['Monto original']); if(!d||u===null||Math.abs(u)<1e-9)return null;
  const same=purchases.filter(x=>dateKey(x.Fecha)===d); if(!same.length)return null;
  const exact=same.find(x=>Math.abs(Math.abs(numOrNull(x['Monto original'])||0)-Math.abs(u))<0.01);
  const pick=exact||(same.length===1?same[0]:null);
  if(pick){const a=Math.abs(numOrNull(pick['Monto ARS'])||0),uu=Math.abs(numOrNull(pick['Monto original'])||0);if(a>0&&uu>0)return {rate:a/uu,source:'OPERACIÓN REAL'};}
  const a=same.reduce((s,x)=>s+Math.abs(numOrNull(x['Monto ARS'])||0),0),uu=same.reduce((s,x)=>s+Math.abs(numOrNull(x['Monto original'])||0),0);
  return a>0&&uu>0?{rate:a/uu,source:'OPERACIÓN REAL PROMEDIO'}:null;
}
const updates=[];
for(const r of rows){
  if(String(r.Clase||'')!=='Egreso'||String(r['Moneda original']||'').toUpperCase()!=='USD'||String(r['Estado revisión']||'').toUpperCase()==='ANULADO')continue;
  const ars=numOrNull(r['Monto ARS']),usd=numOrNull(r['Monto original']);
  if(usd===null||Math.abs(usd)<1e-12)continue;

  const existingRate=numOrNull(r['Cotización ARS']);
  let rate=(existingRate&&existingRate>0)?existingRate:null;
  let source=rate?String(r['Fuente cotización']||'COTIZACIÓN REGISTRADA'):null;

  // Si ya existe Monto ARS pero falta cotización, inferir la cotización desde el propio registro.
  if(!rate && ars!==null && Math.abs(ars)>1e-12){
    rate=Math.abs(ars/usd);
    source=String(r['Fuente cotización']||'COTIZACIÓN REGISTRADA');
  }

  // Si todavía falta cotización, priorizar operación real del día y luego blue histórico.
  if(!rate){
    const real=realRate(r);
    if(real){rate=real.rate;source=real.source;}
    else {const b=blueForDate(dateKey(r.Fecha));if(b){rate=b.rate;source=b.source;}}
  }

  if(!(rate&&rate>0))continue;

  // Regla estructural: todo Egreso USD valuado debe guardar también su equivalente ARS.
  // Se conserva Moneda original / Monto original; NO aplica a transferencias ni pagos de tarjeta.
  const arsEq=(ars!==null && Math.abs(ars)>1e-12) ? ars : Math.abs(usd)*rate;
  const needsArs=ars===null || Math.abs(ars)<1e-12;
  const needsRate=!(existingRate&&existingRate>0);
  if(!needsArs && !needsRate)continue;

  updates.push({json:{
    ID:r.ID,
    'Monto ARS':arsEq,
    'Cotización ARS':rate,
    'Fuente cotización':source,
    _has_updates:true
  }});
}
if(!updates.length)return [{json:{_has_updates:false,_message:'Sin equivalentes/cotizaciones USD pendientes'}}];
return updates;
